/* Valyria's original offline interaction study. No transport, credentials, agents or script execution. */
'use strict';
const M = window.ValyriaLayout;
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const profiles = {
  mira:{name:'Mira',game:'asterfall',id:'AF · 01',connection:'preview-asterfall-mira',room:'The Lantern Court'},
  rowan:{name:'Rowan',game:'asterfall',id:'AF · 02',connection:'preview-asterfall-rowan',room:'The Glass Gallery'},
  quinn:{name:'Quinn',game:'northreach',id:'NR · 01',connection:'preview-northreach-quinn',room:'The Northern Gate'},
  sable:{name:'Sable',game:'northreach',id:'NR · 02',connection:'preview-northreach-sable',room:'The Harbor Steps'}
};
const games = {asterfall:{name:'Asterfall',members:['mira','rowan']},northreach:{name:'Northreach',members:['quinn','sable']}};
const symbols={Main:'▤',Public:'#',Roleplay:'≋',Pages:'↗',Staff:'◇',Notes:'✎',Activity:'◷'};
const initialScript='-- Local example · never executed by this study\n-- Destination: the selected fictional profile\n\nfunction on_courtyard_arrival(name)\n  world.Note(name .. " arrives in the courtyard.")\nend\n\n-- Ctrl+Space opens the completion example.\nworld.';
const STORAGE='valyria-workspace-study-v3';
let storageAvailable=true;
let state={version:3,profile:'mira',expanded:['mira'],theme:'system',accent:'red',scale:1,outputSize:14,layouts:{},drafts:{},notes:{},scripts:{},routing:{},logging:{},review:{},automation:{},positions:{},samples:{},read:{}};
try {
  const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');
  if(saved?.version===3){
    if(profiles[saved.profile])state.profile=saved.profile;
    if(['system','light','dark'].includes(saved.theme))state.theme=saved.theme;
    if(['red','blue'].includes(saved.accent))state.accent=saved.accent;
    if([.9,1,1.1,1.2].includes(saved.scale))state.scale=saved.scale;
    if([12,13,14,15,16,18].includes(saved.outputSize))state.outputSize=saved.outputSize;
    if(Array.isArray(saved.expanded))state.expanded=saved.expanded.filter(x=>profiles[x]);
    for(const field of ['drafts','notes','scripts','routing','logging','review','automation','positions','samples','read']){
      if(saved[field]&&typeof saved[field]==='object'&&!Array.isArray(saved[field]))state[field]=saved[field];
    }
    for(const id of Object.keys(profiles))if(M.validate(saved.layouts?.[id],id))state.layouts[id]=saved.layouts[id];
  }
} catch { storageAvailable=false; }
for(const id of Object.keys(profiles)){
  if(!state.layouts[id])state.layouts[id]=M.initial(id);
  if(typeof state.scripts[id]!=='string')state.scripts[id]=initialScript;
  if(typeof state.notes[id]!=='string')state.notes[id]='Scene notes\n\n• Meet Rowan by the west arch.\n• Ask about the sealed letter.\n• Leave room for the next player’s reply.\n\nPrivate to this fictional profile. Saved in this browser only.';
  if(!Array.isArray(state.automation[id]))state.automation[id]=[{type:'Alias',name:'Quick glance',match:'^glance$',action:'look',enabled:true},{type:'Trigger',name:'Page highlight',match:'* pages you: *',action:'Highlight matching text',enabled:true}];
}
const media=matchMedia('(prefers-color-scheme: dark)');
let toastTimer,saveTimer,dragTab=null,dragCanceled=false,lastTool='',commandIndex=0,commandItems=[],activePreview=null;
const ws=()=>state.layouts[state.profile];
const profile=()=>profiles[state.profile];
const channelOf=tab=>String(tab).split(':')[1];
const ownerOf=tab=>String(tab).split(':')[0];
const tabLabel=tab=>`${profiles[ownerOf(tab)]?.name||''} / ${channelOf(tab)}`;
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;}$('layout-status').textContent=storageAvailable?'Layout saved locally':'Storage unavailable · session only';}
function soonSave(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,180);}
function toast(text){$('toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',4200);}
function appearance(){document.documentElement.dataset.theme=state.theme==='system'?(media.matches?'dark':'light'):state.theme;document.documentElement.dataset.accent=state.accent;document.documentElement.style.setProperty('--ui-scale',state.scale);document.documentElement.style.setProperty('--output-size',`${state.outputSize}px`);}
media.addEventListener('change',appearance);
function saveDraft(){state.drafts[ws().active]=$('draft').value;soonSave();}
function setProfile(id,tab){saveDraft();capturePositions();state.profile=id;if(!state.expanded.includes(id))state.expanded.push(id);if(tab)M.activate(ws(),tab);state.read[ws().active]=true;render();persist();}
function selectTab(tab){const id=ownerOf(tab);if(id!==state.profile){setProfile(id,tab);return;}saveDraft();capturePositions();M.activate(ws(),tab);state.read[tab]=true;render();persist();}
function capturePositions(){document.querySelectorAll('.transcript[data-tab]').forEach(el=>{state.positions[el.dataset.tab]=el.scrollTop;});}
function renderNavigation(){
  const game=games[profile().game];$('game-title').textContent=game.name;
  const pending=3-Object.keys(state.review[state.profile]||{}).filter(k=>['alias','trigger','note'].includes(k)).length;
  document.querySelector('[data-tool="review"] .count').textContent=String(pending);
  document.querySelectorAll('[data-game]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.game===profile().game));
  $('characters').innerHTML=game.members.map(id=>{
    const p=profiles[id],expanded=state.expanded.includes(id);
    return `<div class="character-tree"><div class="character-row"><button class="character" data-profile="${id}" aria-pressed="${id===state.profile}"><span class="avatar">${p.name[0]}</span><span><strong>${p.name}</strong><small>Offline preview · ${p.id}</small></span></button><button class="character-expand icon-button" data-expand="${id}" aria-expanded="${expanded}" aria-controls="channels-${id}" aria-label="${expanded?'Collapse':'Expand'} ${p.name}’s channels">${expanded?'⌄':'›'}</button></div><div id="channels-${id}" class="channel-list" ${expanded?'':'hidden'}>${M.CHANNELS.map(c=>`<button class="channel" data-channel="${id}:${c}" ${id===state.profile&&ws().active===`${id}:${c}`?'aria-current="page"':''}><span class="channel-symbol">${symbols[c]}</span><span>${c}</span>${['Public','Pages'].includes(c)&&!state.read[id+':'+c]&&!(id===state.profile&&ws().active===`${id}:${c}`)?`<span class="unread" aria-label="${c==='Pages'?1:3} example unread messages">${c==='Pages'?1:3}</span>`:''}</button>`).join('')}</div></div>`;
  }).join('');
  document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>setProfile(b.dataset.profile));
  document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{const id=b.dataset.expand;state.expanded=state.expanded.includes(id)?state.expanded.filter(p=>p!==id):[...state.expanded,id];renderNavigation();persist();document.querySelector(`[data-expand="${id}"]`)?.focus();});
  document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{selectTab(b.dataset.channel);if(innerWidth<=950){$('app').classList.remove('nav-open');$('nav-toggle').setAttribute('aria-expanded','false');}});
  $('breadcrumb-game').textContent=game.name;$('breadcrumb-profile').textContent=profile().name;$('profile-id').textContent=profile().id;
  $('footer-profile').textContent=profile().name;$('footer-avatar').textContent=profile().name[0];
  $('workspace-name').textContent=profile().room;$('workspace-subtitle').textContent=`${game.name} · ${profile().name}’s workspace`;
}
function sampleMessages(channel,id=state.profile){
  const own=profiles[id].name;
  const samples={Public:[['Quinn','Is anyone heading to the gallery?','18:42'],['Rowan','I’ll be there after the bells.','18:43'],[own,'We’re by the west arch. Come find us.','18:44']],Pages:[['Rowan','Did you get a chance to read the letter?','18:41'],[own,'Not yet. I’ll bring it to the courtyard.','18:43']],Roleplay:[['Sable','The lantern gutters as the gate opens.','18:40'],[own,'A pause, then a glance toward the gallery.','18:42']],Staff:[['Guide','Scene support is available in the gallery.','18:35'],[own,'Thank you. We have everything we need.','18:38']]};
  return samples[channel]||samples.Public;
}
function roomMarkup(id){
  const p=profiles[id],north=p.game==='northreach';
  return `<h3>${esc(p.room)}</h3><div class="room-meta">${north?'NORTHREACH · UPPER CITY':'ASTERFALL · OLD CITY'} · EVENING</div><button class="room-image" aria-label="Open fictional courtyard image"><img src="courtyard-study.svg" alt="Line illustration of the courtyard arches"><span>Room image · original study illustration ↗</span></button><div class="room-lead"><p>${north?'Wind draws a low note through the gatehouse. Beyond the arch, a road follows the ridge toward the sea.':'Evening settles over the courtyard. Lanterns hang beneath the covered walk, their light catching the rain on the stone.'}</p><p>${north?'A lantern burns beside the watchman’s door. Footsteps sound on the stair above.':'A narrow stair leads up to the gallery. Beneath it, an open arch gives onto the gardens.'}</p></div><p class="arrival"><span class="output-time">18:41</span>Rowan arrives from the gardens.</p><p><span class="speaker">Rowan</span> brushes the rain from one sleeve. “I thought I might find you here.”</p><p><span class="speaker">${esc(p.name)}</span> looks up from the letter. “Then your timing is better than mine.”</p><p class="exits">Exits &nbsp; Gallery · Gardens · Market</p>${Object.entries(state.routing).filter(([tab,mode])=>tab.startsWith(id+':')&&mode==='both').map(([tab])=>`<div class="routed-sample"><div class="day-line">${esc(channelOf(tab))} · ALSO IN MAIN</div>${sampleMessages(channelOf(tab),id).slice(0,1).map(([name,text])=>`<p><span class="speaker">[${esc(channelOf(tab))}] ${esc(name)}</span> ${esc(text)}</p>`).join('')}</div>`).join('')}`;
}
function transcriptMarkup(tab){
  const channel=channelOf(tab),id=ownerOf(tab),own=profiles[id].name;
  if(channel==='Main')return roomMarkup(id);
  if(channel==='Notes')return `<textarea class="local-notes" aria-label="${esc(own)}’s private notes">${esc(state.notes[id])}</textarea>`;
  if(channel==='Activity'){const pending=3-Object.keys(state.review[id]||{}).filter(k=>['alias','trigger','note'].includes(k)).length;return `<div class="day-line">LOCAL WORKSPACE</div><div class="activity-row"><span class="activity-dot"></span><div><strong>Workspace restored</strong><small>Your channels and drafts are ready.</small></div></div><div class="activity-row"><span class="activity-dot"></span><div><strong>${pending} change${pending===1?'':'s'} awaiting review</strong><small>Fixed example proposal · local decisions only.</small></div></div><div class="activity-row"><span class="activity-dot"></span><div><strong>Preview mode</strong><small>No connection or background agent.</small></div></div>`;}
  return `<div class="day-line">FICTIONAL TRANSCRIPT · TODAY</div>${sampleMessages(channel,id).map(([name,text,time])=>`<div class="chat-message ${name===own?'own':''}"><div class="chat-meta"><span class="chat-avatar">${esc(name[0])}</span><strong>${esc(name)}</strong><time>${time}</time></div><p>${esc(text)}</p></div>`).join('')}`;
}
function makePane(group, floating=false){
  const tab=group.active,channel=channelOf(tab),p=profiles[ownerOf(tab)];
  const pane=document.createElement('section');pane.className='pane'+(ws().active===tab?' is-current':'');pane.dataset.group=group.id;pane.setAttribute('aria-label',`${p.name} · ${group.tabs.map(channelOf).join(', ')} pane`);
  pane.innerHTML=`<header class="pane-top"><div class="tabs" role="tablist" aria-label="${esc(p.name)}’s ${esc(group.tabs.map(channelOf).join(', '))} tabs">${group.tabs.map(t=>`<button class="tab" role="tab" id="tab-${esc(t)}" aria-controls="panel-${esc(t)}" aria-selected="${t===tab}" tabindex="${t===tab?'0':'-1'}" draggable="true" data-tab="${esc(t)}">${esc(channelOf(t))}</button>`).join('')}</div><div class="pane-tools"><button data-pane-arrange="${esc(tab)}" aria-label="Arrange ${esc(channel)} tab" title="Arrange ${esc(channel)} tab">⊞</button><button data-pane-route="${esc(tab)}" aria-label="${esc(channel)} channel settings" title="Channel settings">•••</button></div></header><div class="pane-identity"><span>${esc(p.name)}</span><span>·</span><span>${games[p.game].name}</span><span class="channel-type">${channel==='Notes'?'PRIVATE NOTES':channel==='Activity'?'LOCAL EVENTS':'OUTPUT'}</span></div><div class="transcript" id="panel-${esc(tab)}" role="tabpanel" aria-label="${esc(p.name)} ${esc(channel)} transcript" ${floating?'':`aria-labelledby="tab-${esc(tab)}"`} tabindex="0" data-tab="${esc(tab)}">${transcriptMarkup(tab)}</div><footer class="pane-foot"><span><i class="live-marker"></i>${channel==='Notes'?'Saved locally':'Example output'}</span><span>${channel==='Main'?'UTF-8':channel==='Activity'?'Offline':channel==='Notes'?'No sharing':state.routing[tab]==='both'?'Also in Main':'Separate channel'}</span></footer><div class="drop-preview" hidden><span></span></div>`;
  pane.querySelectorAll('.tab').forEach(button=>{
    button.onclick=()=>{selectTab(button.dataset.tab);document.getElementById('tab-'+button.dataset.tab)?.focus();};
    button.ondragstart=e=>{dragTab=button.dataset.tab;dragCanceled=false;e.dataTransfer.setData('text/plain',dragTab);e.dataTransfer.effectAllowed='move';document.body.classList.add('dragging');};
    button.ondragend=clearDrag;
    button.ondragover=e=>{if(!dragTab||dragCanceled)return;e.preventDefault();e.stopPropagation();clearPreviews();button.classList.add('drop-before');e.dataTransfer.dropEffect='move';};
    button.ondrop=e=>{if(!dragTab||dragCanceled)return;e.preventDefault();e.stopPropagation();const moving=dragTab;clearDrag();moveTab(moving,group.id,'join',button.dataset.tab);};
    button.onkeydown=e=>{
      if(e.ctrlKey&&e.shiftKey&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const i=group.tabs.indexOf(button.dataset.tab),other=i+(e.key==='ArrowLeft'?-1:1);if(other>=0&&other<group.tabs.length){[group.tabs[i],group.tabs[other]]=[group.tabs[other],group.tabs[i]];render();persist();document.getElementById('tab-'+button.dataset.tab)?.focus();}return;}
      if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const i=group.tabs.indexOf(button.dataset.tab),next=e.key==='Home'?0:e.key==='End'?group.tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+group.tabs.length)%group.tabs.length;selectTab(group.tabs[next]);document.getElementById('tab-'+group.tabs[next])?.focus();}
    };
  });
  pane.querySelector('[data-pane-arrange]').onclick=()=>openPlacement(tab);
  pane.querySelector('.room-image')?.addEventListener('click',()=>{showDialog('Room image','INLINE IMAGE EXAMPLE');$('tool-body').innerHTML='<div class="image-preview"><img src="courtyard-study.svg" alt="Original line illustration of a fictional courtyard"></div><p class="subtle">Original placeholder illustration retained from the earlier workspace study. This browser example demonstrates image placement and opening; it does not decode MXP/Pueblo or route images from a server.</p>';});
  pane.querySelector('[data-pane-route]').onclick=()=>openTool('routing',tab);
  const body=pane.querySelector('.transcript');body.scrollTop=Number(state.positions[tab])||0;
  body.addEventListener('scroll',()=>{state.positions[tab]=body.scrollTop;soonSave();});
  body.addEventListener('pointerdown',()=>{if(ws().active!==tab){saveDraft();M.activate(ws(),tab);renderNavigation();renderComposer();document.querySelectorAll('.pane').forEach(n=>n.classList.toggle('is-current',n.querySelector('.transcript')?.dataset.tab===tab));persist();}});
  pane.querySelector('.local-notes')?.addEventListener('input',e=>{state.notes[ownerOf(tab)]=e.target.value;soonSave();});
  if(!floating){pane.ondragover=e=>{if(!dragTab||dragCanceled)return;e.preventDefault();clearPreviews();const side=sideAt(e,pane),preview=pane.querySelector('.drop-preview');preview.hidden=false;preview.dataset.side=side;preview.firstElementChild.textContent=side==='join'?'Join tabs':`Place ${side}`;activePreview=preview;e.dataTransfer.dropEffect='move';};pane.ondragleave=e=>{if(!pane.contains(e.relatedTarget))pane.querySelector('.drop-preview').hidden=true;};pane.ondrop=e=>{if(!dragTab||dragCanceled)return;e.preventDefault();const side=sideAt(e,pane),moving=dragTab;clearDrag();moveTab(moving,group.id,side);};}
  return pane;
}
function sideAt(e,pane){const r=pane.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;const edges=[['left',x],['right',1-x],['above',y],['below',1-y]].sort((a,b)=>a[1]-b[1]);return edges[0][1]<.23?edges[0][0]:'join';}
function clearPreviews(){document.querySelectorAll('.drop-preview').forEach(p=>p.hidden=true);document.querySelectorAll('.drop-before').forEach(p=>p.classList.remove('drop-before'));activePreview=null;}
function clearDrag(){dragTab=null;clearPreviews();document.body.classList.remove('dragging');}
function moveTab(tab,target,side,before){saveDraft();capturePositions();if(M.move(ws(),tab,target,side,before)){render();persist();toast(`${channelOf(tab)} ${side==='join'?'joined the tab group':`placed ${side}`}. Its character and draft are retained.`);document.getElementById('tab-'+tab)?.focus();}else toast('Choose another pane, or join tabs in this group.');}
function makeNode(node){
  if(node.type==='group')return makePane(node);
  const split=document.createElement('div');split.className=`split axis-${node.axis}`;split.dataset.split=node.id;
  const a=document.createElement('div'),b=document.createElement('div');a.className=b.className='split-child';a.style.flex=`${node.ratio} 1 0%`;b.style.flex=`${1-node.ratio} 1 0%`;a.append(makeNode(node.a));b.append(makeNode(node.b));
  const handle=document.createElement('div');handle.className='splitter';handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-label',`Resize ${node.axis==='x'?'side-by-side':'stacked'} panes`);handle.setAttribute('aria-orientation',node.axis==='x'?'vertical':'horizontal');handle.setAttribute('aria-valuemin','15');handle.setAttribute('aria-valuemax','85');handle.setAttribute('aria-valuenow',Math.round(node.ratio*100));
  const setRatio=value=>{M.resize(ws(),node.id,value);a.style.flex=`${node.ratio} 1 0%`;b.style.flex=`${1-node.ratio} 1 0%`;handle.setAttribute('aria-valuenow',Math.round(node.ratio*100));};
  handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();handle.setPointerCapture(e.pointerId);const rect=split.getBoundingClientRect();handle.onpointermove=event=>setRatio(node.axis==='x'?(event.clientX-rect.left)/rect.width:(event.clientY-rect.top)/rect.height);handle.onpointerup=()=>{handle.onpointermove=null;persist();};};
  handle.onkeydown=e=>{const keys=node.axis==='x'?['ArrowLeft','ArrowRight']:['ArrowUp','ArrowDown'];if(keys.includes(e.key)){e.preventDefault();setRatio(node.ratio+(e.key===keys[0]?-.05:.05));persist();}if(e.key==='Home'||e.key==='End'){e.preventDefault();setRatio(e.key==='Home'?.15:.85);persist();}};
  split.append(a,handle,b);return split;
}
function makeFloat(f){
  const el=document.createElement('section');el.className='floating-pane';el.dataset.float=f.id;el.setAttribute('aria-label',`Detached preview of ${tabLabel(f.tab)}`);
  const bounds=$('dock-area').getBoundingClientRect();const w=Math.min(f.w,Math.max(220,bounds.width-20)),h=Math.min(f.h,Math.max(190,bounds.height-20));el.style.width=w+'px';el.style.height=h+'px';el.style.left=Math.max(0,Math.min(f.x,bounds.width-w))+'px';el.style.top=Math.max(0,Math.min(f.y,bounds.height-h))+'px';
  const header=document.createElement('div');header.className='float-title';header.tabIndex=0;header.setAttribute('aria-label',`Move detached ${channelOf(f.tab)} preview with arrow keys`);header.innerHTML=`<strong>${esc(tabLabel(f.tab))}</strong><small>DETACHED PREVIEW</small><button>↙ Rejoin</button>`;
  header.querySelector('button').onclick=()=>{capturePositions();M.rejoin(ws(),f.tab);render();persist();toast('Channel rejoined its workspace.');};
  const setPosition=(x,y)=>{const area=$('dock-area').getBoundingClientRect();f.x=Math.max(0,Math.min(x,area.width-el.offsetWidth));f.y=Math.max(0,Math.min(y,area.height-el.offsetHeight));el.style.left=f.x+'px';el.style.top=f.y+'px';};
  header.onpointerdown=e=>{if(e.target.closest('button'))return;e.preventDefault();header.setPointerCapture(e.pointerId);const x=e.clientX,y=e.clientY,left=parseFloat(el.style.left),top=parseFloat(el.style.top);header.onpointermove=ev=>setPosition(left+ev.clientX-x,top+ev.clientY-y);header.onpointerup=()=>{header.onpointermove=null;persist();};};
  header.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const step=e.shiftKey?30:10;setPosition(parseFloat(el.style.left)+(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0),parseFloat(el.style.top)+(e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0));persist();}};
  el.append(header,makePane({id:f.id,tabs:[f.tab],active:f.tab},true));
  const observer=new ResizeObserver(()=>{if(el.isConnected){f.w=el.offsetWidth;f.h=el.offsetHeight;soonSave();}else observer.disconnect();});observer.observe(el);el._resizeObserver=observer;return el;
}
function renderComposer(){const tab=ws().active,p=profiles[ownerOf(tab)],channel=channelOf(tab),local=['Notes','Activity'].includes(channel);$('send-destination').textContent=`${p.name} / ${games[p.game].name} / ${channel}`;$('route-detail').textContent=local?`${p.connection} · local-only ${channel.toLowerCase()}`:`${p.connection} · ${channel==='Main'?'main command stream':channel==='Pages'?'page-route example':channel.toLowerCase()+' route example'}`;$('draft').value=typeof state.drafts[tab]==='string'?state.drafts[tab]:'';$('draft').placeholder=local?'Local note draft…':'Write a command or a pose…';$('preview-send').disabled=local;$('preview-send').title=local?'This local view has no send destination':'Show a local preview; no command is sent';$('draft-status').textContent=storageAvailable?'Draft saved locally':'Session draft only';}
function render(){appearance();renderNavigation();$('dock-root').replaceChildren();if(ws().tree)$('dock-root').append(makeNode(ws().tree));else $('dock-root').innerHTML='<div class="dock-help">All channels are detached in this preview.<br>Use Rejoin on a detached pane or Arrange to restore a channel.</div>';$('floating-layer').querySelectorAll('.floating-pane').forEach(el=>el._resizeObserver?.disconnect());$('floating-layer').replaceChildren(...ws().floating.map(makeFloat));renderComposer();requestAnimationFrame(()=>document.querySelectorAll('.transcript[data-tab]').forEach(el=>el.scrollTop=Number(state.positions[el.dataset.tab])||0));}
function openPlacement(tab=ws().active){
  $('move-tab').innerHTML=M.CHANNELS.map(c=>`<option value="${state.profile}:${c}">${esc(profile().name)} / ${c}</option>`).join('');$('move-tab').value=tab;
  $('move-target').innerHTML=M.groups(ws()).map(g=>`<option value="${g.id}">${esc(g.tabs.map(channelOf).join(' + '))}</option>`).join('');const own=M.owner(ws(),tab),other=M.groups(ws()).find(g=>g.id!==own?.id);$('move-target').value=other?.id||own?.id||'';
  updatePlacement();$('placement-dialog').showModal();
}
function updatePlacement(){const tab=$('move-tab').value,isFloat=ws().floating.some(f=>f.tab===tab);$('detach-tab').disabled=isFloat;$('rejoin-tab').disabled=!isFloat;document.querySelectorAll('[data-place]').forEach(b=>b.disabled=!$('move-target').value);}
$('move-tab').onchange=updatePlacement;$('placement-close').onclick=()=>$('placement-dialog').close();
document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const tab=$('move-tab').value,target=$('move-target').value;$('placement-dialog').close();moveTab(tab,target,b.dataset.place);});
$('detach-tab').onclick=()=>{saveDraft();capturePositions();const tab=$('move-tab').value;M.detach(ws(),tab);$('placement-dialog').close();render();persist();toast('Detached inside the browser preview. Native window behavior is a separate acceptance requirement.');};
$('rejoin-tab').onclick=()=>{const tab=$('move-tab').value;M.rejoin(ws(),tab);$('placement-dialog').close();render();persist();toast('Channel rejoined the workspace.');};
function showDialog(title,kicker='WORKSPACE TOOLS'){lastTool=title;$('tool-title').textContent=title;$('tool-kicker').textContent=kicker;if(!$('tool-dialog').open)$('tool-dialog').showModal();}
function toolSettings(){
  showDialog('Appearance & workspace','VALYRIA SETTINGS');
  $('tool-body').innerHTML=`<p class="tool-intro">Quiet surfaces, readable output, and one accent. Settings apply to this browser study.</p><div class="field-row"><div><strong>Appearance</strong><small>System follows your operating system’s preference.</small></div><div class="segmented" aria-label="Appearance">${['system','light','dark'].map(t=>`<button data-theme-option="${t}" aria-pressed="${state.theme===t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div><div class="field-row"><div><strong>Accent color</strong><small>Valyria red is the default. Output colors are independent.</small></div><div class="segmented" aria-label="Accent color"><button data-accent-option="red" aria-pressed="${state.accent==='red'}"><span class="accent-swatch"></span>Red</button><button data-accent-option="blue" aria-pressed="${state.accent==='blue'}"><span class="accent-swatch blue"></span>Blue</button></div></div><label class="field-row"><span><strong>Interface scale</strong><small>Scales general interface text. Browser zoom also works.</small></span><select id="ui-scale">${[.9,1,1.1,1.2].map(n=>`<option value="${n}" ${state.scale===n?'selected':''}>${Math.round(n*100)}%</option>`).join('')}</select></label><label class="field-row"><span><strong>Transcript size</strong><small>Cascadia Code, with Consolas as a fallback.</small></span><select id="output-size">${[12,13,14,15,16,18].map(n=>`<option value="${n}" ${state.outputSize===n?'selected':''}>${n} px</option>`).join('')}</select></label><div class="theme-example"><span class="status-dot"></span><span>Selected channel · ${esc(profile().name)} / Public</span><button class="primary" id="theme-example-button">Preview focus</button></div><div class="inline-notice">Windows resize, snap layouts, title-bar system menu, and detached windows belong to the native operating-system frame. This browser study does not simulate working OS controls.</div><p class="subtle">High contrast and reduced motion follow system preferences. Keyboard focus remains visible. Themes and layouts are saved independently from your local drafts.</p>`;
  document.querySelectorAll('[data-theme-option]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.themeOption;appearance();persist();toolSettings();document.querySelector(`[data-theme-option="${state.theme}"]`)?.focus();});
  document.querySelectorAll('[data-accent-option]').forEach(b=>b.onclick=()=>{state.accent=b.dataset.accentOption;appearance();persist();toolSettings();document.querySelector(`[data-accent-option="${state.accent}"]`)?.focus();});
  $('ui-scale').onchange=e=>{state.scale=Number(e.target.value);appearance();persist();};$('output-size').onchange=e=>{state.outputSize=Number(e.target.value);appearance();persist();};$('theme-example-button').onclick=()=>toast('Accent, focus and selection share semantic theme roles.');
}
const completions=[{name:'world.Note',args:'("message")',detail:'Write a local output line'},{name:'world.Send',args:'("command")',detail:'Native client API · not executed here'},{name:'world.GetVariable',args:'("name")',detail:'Read a script variable'},{name:'world.SetVariable',args:'("name", "value")',detail:'Set a script variable'}];
function toolEditor(){
  showDialog('Script editor','LOCAL EDITOR DEMONSTRATION');
  $('tool-body').innerHTML=`<p class="tool-intro">Editing <strong>arrival.lua</strong> for <strong>${esc(profile().name)} / ${games[profile().game].name}</strong>. This local buffer is saved per character. No code is executed.</p><div class="editor-toolbar"><div><strong>arrival.lua</strong> <span>· Lua</span></div><button class="secondary" id="completion-open">Complete <kbd>Ctrl Space</kbd></button></div><div class="code-editor"><div class="line-numbers" aria-hidden="true" id="line-numbers"></div><textarea id="script-buffer" aria-label="Lua script editor" spellcheck="false">${esc(state.scripts[state.profile])}</textarea></div><div class="editor-footer"><span id="editor-save-state">Saved locally</span><span>UTF-8 · Tab moves focus · example API list</span></div><div id="completion-list" class="completion-list" hidden></div><div class="inline-notice" id="script-check-result">Completion inserts from a small, fixed example API list. This study has no Lua parser, language server, or connection to a running world.</div><div class="dialog-actions"><button class="secondary" id="script-review">Open agent review</button><button class="primary" id="script-check">Check example</button></div>`;
  const buffer=$('script-buffer');const update=()=>{$('line-numbers').textContent=Array.from({length:buffer.value.split('\n').length},(_,i)=>i+1).join('\n');state.scripts[state.profile]=buffer.value;$('editor-save-state').textContent='Saved locally';soonSave();};update();
  const complete=()=>{const left=buffer.value.slice(0,buffer.selectionStart),token=left.match(/[\w.]+$/)?.[0]||'';const choices=completions.filter(c=>c.name.toLowerCase().startsWith(token.toLowerCase()));$('completion-list').hidden=false;$('completion-list').innerHTML=choices.length?choices.map(c=>`<button data-completion="${c.name}"><span>${c.name}</span><small>${c.detail}</small></button>`).join(''):'<div class="subtle">No example completion. Try typing world.</div>';document.querySelectorAll('[data-completion]').forEach(b=>b.onclick=()=>{const c=completions.find(x=>x.name===b.dataset.completion);const end=buffer.selectionStart,start=end-token.length;buffer.setRangeText(c.name+c.args,start,end,'end');$('completion-list').hidden=true;update();buffer.focus();});$('completion-list').querySelector('button')?.focus();};
  buffer.oninput=update;buffer.onscroll=()=>$('line-numbers').scrollTop=buffer.scrollTop;buffer.onkeydown=e=>{if(e.ctrlKey&&e.code==='Space'){e.preventDefault();complete();}};$('completion-open').onclick=complete;
  $('completion-list').onkeydown=e=>{const buttons=[...$('completion-list').querySelectorAll('button')],current=buttons.indexOf(document.activeElement);if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)&&buttons.length){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(current+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();}if(e.key==='Enter'&&current>=0){e.preventDefault();buttons[current].click();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();$('completion-list').hidden=true;buffer.focus();}};
  const indent=document.createElement('button');indent.className='secondary';indent.textContent='Indent 2 spaces';indent.onclick=()=>{buffer.setRangeText('  ',buffer.selectionStart,buffer.selectionEnd,'end');update();buffer.focus();};$('completion-open').before(indent);
  $('script-check').onclick=()=>{const flags=[['os.execute','external process call'],['io.open','filesystem access'],['world.Send','game command call']].filter(([needle])=>buffer.value.includes(needle));$('script-check-result').textContent=flags.length?'Review needed: '+flags.map(x=>x[1]).join(', ')+'. This literal-text check does not establish script safety. Nothing was executed.':'Example check: no configured review keywords found. This is not syntax validation or a safety guarantee. Nothing was executed.';$('script-check-result').setAttribute('role','status');};$('script-review').onclick=()=>toolReview();
}
const proposalDefinitions=[{id:'alias',name:'Add a travel alias',summary:'Typing court would expand to look courtyard in the native client.',diff:'+ Alias: court\n+ Expansion: look courtyard'},{id:'trigger',name:'Highlight arrival messages',summary:'Add a text-only highlight for arrival lines.',diff:'+ Match: * arrives from *\n+ Action: highlight text; preserve routed image ownership'},{id:'note',name:'Add a scene reminder',summary:'Append one line to this character’s private notes.',diff:'+ Ask Rowan about the sealed letter.'}];
function toolReview(){
  showDialog('Review proposed changes','EXAMPLE AGENT WORKFLOW');const status=state.review[state.profile]||{};
  $('tool-body').innerHTML=`<p class="tool-intro">A prepared example proposal for <strong>${esc(profile().name)} / ${games[profile().game].name}</strong>. Review each change before applying it to the local preview.</p><div class="review-scope"><span>Source <strong>Fixed sample</strong></span><span>Scope <strong>This character only</strong></span><span>Agent <strong>Not running</strong></span></div>${proposalDefinitions.map(p=>`<label class="proposal"><input type="checkbox" data-proposal="${p.id}" ${status[p.id]?'disabled':'checked'}><span><h3>${p.name}${status[p.id]?` · ${esc(status[p.id])}`:''}</h3><p>${p.summary}</p><div class="diff"><span class="addition">${esc(p.diff)}</span></div></span></label>`).join('')}<p class="review-state" id="review-state">Applying changes updates only this study’s local example configuration. It grants no agent permission and sends no commands.</p><div class="dialog-actions"><button class="secondary" id="review-reset">Reset review status</button><button class="secondary" id="review-reject">Reject selected</button><button class="primary" id="review-apply">Apply selected to preview</button></div>`;
  const act=(apply)=>{const selected=[...document.querySelectorAll('[data-proposal]:checked:not(:disabled)')].map(e=>e.dataset.proposal);if(!selected.length){$('review-state').textContent='Select at least one pending change.';return;}if(!state.review[state.profile])state.review[state.profile]={};for(const id of selected){state.review[state.profile][id]=apply?'Applied locally':'Rejected';if(apply&&id==='note'&&!state.notes[state.profile].includes('• Ask Rowan about the sealed letter.'))state.notes[state.profile]+='\n• Ask Rowan about the sealed letter.';if(apply&&id==='alias'&&!state.automation[state.profile].some(a=>a.proposal==='alias'))state.automation[state.profile].push({type:'Alias',name:'Reviewed court alias',match:'^court$',action:'look courtyard',enabled:true,proposal:'alias'});if(apply&&id==='trigger'&&!state.automation[state.profile].some(a=>a.proposal==='trigger'))state.automation[state.profile].push({type:'Trigger',name:'Reviewed arrival highlight',match:'* arrives from *',action:'Highlight matching text',enabled:true,proposal:'trigger'});}persist();render();toolReview();toast(`${selected.length} example change${selected.length===1?'':'s'} ${apply?'applied locally':'rejected'}. No native configuration changed.`);};
  $('review-apply').onclick=()=>act(true);$('review-reject').onclick=()=>act(false);$('review-reset').onclick=()=>{state.review[state.profile]={};persist();render();toolReview();toast('Review status reset. Previously applied local changes are retained.');};
}
function toolLogging(){window.ValyriaLogging.open({$,esc,state,profile,games,channelOf,ws,persist,sampleMessages,channels:M.CHANNELS,showDialog});}
function toolAutomation(){
  showDialog('Triggers & aliases','LOCAL CONFIGURATION EXAMPLE');
  $('tool-body').innerHTML=`<p class="tool-intro">Example configuration for <strong>${esc(profile().name)}</strong>. Enable switches and reviewed additions persist locally; triggers and aliases do not execute.</p><table class="simple-table"><thead><tr><th>Name / type</th><th>Match</th><th>Action</th><th>State</th></tr></thead><tbody>${state.automation[state.profile].map((a,i)=>`<tr><td>${esc(a.name)}<small>${esc(a.type)}</small></td><td><code>${esc(a.match)}</code></td><td>${esc(a.action)}</td><td><button class="secondary" data-toggle-rule="${i}" aria-pressed="${!!a.enabled}">${a.enabled?'Enabled':'Disabled'}</button></td></tr>`).join('')}</tbody></table><div class="dialog-actions"><button class="secondary" id="auto-editor">Open script editor</button><button class="primary" id="auto-review">Review example additions</button></div>`;
  document.querySelectorAll('[data-toggle-rule]').forEach(b=>b.onclick=()=>{const a=state.automation[state.profile][Number(b.dataset.toggleRule)];a.enabled=!a.enabled;persist();toolAutomation();});$('auto-editor').onclick=toolEditor;$('auto-review').onclick=toolReview;
}
function toolRouting(tab=ws().active){
  showDialog('Channel settings','FILTERED OUTPUT STREAMS');const c=channelOf(tab),id=ownerOf(tab),local=['Main','Notes','Activity'].includes(c);
  $('tool-body').innerHTML=`<p class="tool-intro"><strong>${esc(profiles[id].name)} / ${games[profiles[id].game].name} / ${esc(c)}</strong></p><p class="tool-intro">A channel is a filtered view of this character’s output, such as pages, roleplay, or staff messages. It does not have to be a server-native channel.</p>${local?`<div class="inline-notice">${c==='Main'?'Main is the character’s primary output and command stream. Other channels can also appear here.':'This is a local workspace view. It has no game command route.'}</div>`:`<label class="field-row"><span><strong>Where to show this stream</strong><small>Changing this preview keeps the channel tab available.</small></span><select id="channel-routing"><option value="separate" ${state.routing[tab]!=='both'?'selected':''}>Separate channel only</option><option value="both" ${state.routing[tab]==='both'?'selected':''}>Show in Main as well</option></select></label><div class="inline-notice">This preference adds or removes a clearly labeled sample in Main. Production filter matching and image routing are not changed by the study.</div>`}<div class="field-row"><div><strong>Connection identity</strong><small>Arrangement and display labels never change this owner.</small></div><code>${esc(profiles[id].connection)}</code></div><p class="subtle">Native implementation requirement: an inline image follows its matching text into the same stream. Tabs, joined groups, and detached panes are presentations of that same channel identity.</p><div class="dialog-actions"><button class="primary" id="route-arrange">Arrange this channel</button></div>`;
  if(!local)$('channel-routing').onchange=e=>{state.routing[tab]=e.target.value;capturePositions();render();persist();toast(`${c} is ${e.target.value==='both'?'also included in Main':'shown separately'} in this preview.`);};$('route-arrange').onclick=()=>{$('tool-dialog').close();openPlacement(tab);};
}
function toolProfiles(){showDialog('Your game profiles','FICTIONAL CONNECTION IDENTITIES');$('tool-body').innerHTML=`<p class="tool-intro">Characters are your own logins. Each owns its command route, drafts, channels, and layout. These examples contain no server addresses or credentials.</p><table class="simple-table"><thead><tr><th>Game / character</th><th>Stable connection identity</th><th>Workspace</th></tr></thead><tbody>${Object.entries(profiles).map(([id,p])=>`<tr><td>${p.name}<small>${games[p.game].name}</small></td><td><code>${p.connection}</code></td><td><button class="secondary" data-open-profile="${id}">Open</button></td></tr>`).join('')}</tbody></table><p class="subtle">Adding a real server or login is outside this offline study. Grouping profiles by game is display metadata; it does not merge connections.</p>`;document.querySelectorAll('[data-open-profile]').forEach(b=>b.onclick=()=>{$('tool-dialog').close();setProfile(b.dataset.openProfile);});}
function toolFind(){showDialog('Find in this character’s output','LOCAL TRANSCRIPT SEARCH');$('tool-body').innerHTML=`<p class="tool-intro">Search the fictional transcript samples for <strong>${esc(profile().name)}</strong>. Private notes are included; editor buffers are separate.</p><input class="search-field" id="find-query" placeholder="Search for a word or phrase…" aria-label="Find in transcripts"><div id="find-results"></div>`;const search=()=>{const query=$('find-query').value.trim().toLowerCase();if(!query){$('find-results').innerHTML='<div class="empty-state">Try “letter”, “gallery”, or “Rowan”.</div>';return;}const result=[];for(const c of M.CHANNELS){const box=document.createElement('div');box.innerHTML=transcriptMarkup(`${state.profile}:${c}`);const text=box.textContent||'';const i=text.toLowerCase().indexOf(query);if(i>=0){const start=Math.max(0,i-55),end=Math.min(text.length,i+query.length+100);result.push({c,pre:text.slice(start,i),match:text.slice(i,i+query.length),post:text.slice(i+query.length,end)});}}$('find-results').innerHTML=result.length?result.map(r=>`<div class="search-result"><small>${esc(profile().name)} / ${r.c}</small>${esc(r.pre)}<mark>${esc(r.match)}</mark>${esc(r.post)} <button class="quiet-button" data-find-tab="${state.profile}:${r.c}">Open channel →</button></div>`).join(''):'<div class="empty-state">No matching sample output.</div>';document.querySelectorAll('[data-find-tab]').forEach(b=>b.onclick=()=>{$('tool-dialog').close();selectTab(b.dataset.findTab);});};$('find-query').oninput=search;search();$('find-query').focus();}
function toolShortcuts(){showDialog('Keyboard shortcuts','WORKSPACE ACCESS');$('tool-body').innerHTML=`<div class="shortcut-grid"><span>Search commands and tools</span><kbd>Ctrl K</kbd><span>Open script editor</span><kbd>Ctrl E</kbd><span>Arrange current tab</span><kbd>Ctrl Shift M</kbd><span>Preview a command (nothing sent)</span><kbd>Ctrl Enter</kbd><span>Switch tabs in the focused group</span><kbd>← / → · Home / End</kbd><span>Reorder the focused tab</span><kbd>Ctrl Shift ← / →</kbd><span>Resize a focused separator</span><kbd>Arrow keys · Home / End</kbd><span>Move a detached preview by its header</span><kbd>Arrow keys · Shift for larger steps</kbd><span>Open completion in the editor</span><kbd>Ctrl Space</kbd><span>Dismiss a dialog or cancel a drag</span><kbd>Esc</kbd></div><div class="inline-notice">Use Tab and Shift Tab to reach pane tools and resize handles. Arrange provides every center and edge placement without dragging. Browser-reserved shortcuts can vary by platform.</div>`;}
function toolGuide(){showDialog('A workspace shaped around your play','VALYRIA · INTERACTIVE STUDY');$('tool-body').innerHTML=`<p class="tool-intro">Explore with four fictional characters across two games. Your layout, themes, and local drafts persist in this browser.</p><ol class="guide-list"><li><strong>Navigate your own characters.</strong> Expand several characters at once. Their channels remain nested beneath their owner.</li><li><strong>Arrange any channel.</strong> Drag a tab onto another pane: center joins, edges split. Drop onto a tab to insert before it. The shaded preview names the destination.</li><li><strong>Keep the right destination.</strong> Selecting output updates the composer’s character, game, channel, and stable connection identity.</li><li><strong>Try the tools.</strong> Edit a local script, insert completion examples, review fixed agent proposals, preview log names, or search sample output.</li></ol><div class="inline-notice">This is an original browser prototype of a desktop interface. Detached panes stay inside the browser. There is no game connection, running agent, Lua execution, operating-system window management, or native logging.</div><p class="subtle">The Fourteen Flames mark is the authorized original asset. Native frame, snap, accessibility, performance, and connection routing still require implementation and acceptance in the Windows client.</p>`;}
function openTool(tool,tab){({settings:toolSettings,editor:toolEditor,review:toolReview,logging:toolLogging,automation:toolAutomation,profiles:toolProfiles,find:toolFind,shortcuts:toolShortcuts,guide:toolGuide,routing:()=>toolRouting(tab)})[tool]?.();}
function previewSend(){saveDraft();const tab=ws().active;if(['Notes','Activity'].includes(channelOf(tab)))return;showDialog('Preview command','LOCAL ONLY · NOTHING IS SENT');const text=state.drafts[tab]||'';$('tool-body').innerHTML=`<p class="tool-intro">Destination: <strong>${esc(tabLabel(tab))} / ${games[profile().game].name}</strong></p><div class="field-row"><div><strong>Original connection</strong><small>Stable identity is independent of pane placement.</small></div><code>${esc(profile().connection)}</code></div><div class="filename-preview"><div class="eyebrow">DRAFT · RETAINED AFTER PREVIEW</div><div class="diff">${text?esc(text):'No command entered.'}</div></div><div class="inline-notice">Nothing was sent. Channel prefix expansion, recipients, permissions, and command dispatch require the existing native routing engine.</div><div class="dialog-actions"><button class="primary" id="preview-return">Return to draft</button></div>`;$('preview-return').onclick=()=>{$('tool-dialog').close();$('draft').focus();};}
function resetLayout(){saveDraft();capturePositions();state.layouts[state.profile]=M.initial(state.profile);render();persist();toast('Default pane layout restored. Drafts, notes, scripts and theme retained.');}
function allCommands(){const tools=[['Script editor','editor','Ctrl E'],['Agent review','review','3 sample changes'],['Logging setup','logging','Filename preview'],['Triggers & aliases','automation','Local examples'],['Appearance & workspace','settings','System / Light / Dark'],['Channel settings','routing','Filtered output'],['Find in output','find','Search samples'],['Game profiles','profiles','Your own characters'],['Keyboard shortcuts','shortcuts','Accessibility'],['Prototype guide','guide','Scope & controls']].map(([label,tool,detail])=>({label,detail,run:()=>openTool(tool)}));return [...tools,{label:'Arrange current tab',detail:'Ctrl Shift M',run:()=>openPlacement()},{label:'Reset current layout',detail:'Keeps drafts',run:resetLayout},...games[profile().game].members.flatMap(id=>M.CHANNELS.map(c=>({label:`${profiles[id].name} / ${c}`,detail:'Open channel',run:()=>selectTab(`${id}:${c}`)})))];}
function renderCommands(){const q=$('command-query').value.toLowerCase().trim();commandItems=allCommands().filter(c=>(c.label+' '+c.detail).toLowerCase().includes(q));commandIndex=Math.min(commandIndex,Math.max(0,commandItems.length-1));$('command-results').innerHTML=commandItems.length?commandItems.map((c,i)=>`<button data-command="${i}" aria-selected="${i===commandIndex}"><span>${esc(c.label)}</span><small>${esc(c.detail)}</small></button>`).join(''):'<div class="empty-state">No matching command.</div>';document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>runCommand(Number(b.dataset.command)));}
function runCommand(i){const c=commandItems[i];if(c){$('command-dialog').close();c.run();}}
function openCommands(){$('command-query').value='';commandIndex=0;renderCommands();$('command-dialog').showModal();$('command-query').focus();}
$('command-query').oninput=()=>{commandIndex=0;renderCommands();};$('command-dialog').onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();commandIndex=(commandIndex+(e.key==='ArrowDown'?1:-1)+commandItems.length)%Math.max(1,commandItems.length);renderCommands();document.querySelector(`[data-command="${commandIndex}"]`)?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'){e.preventDefault();runCommand(commandIndex);}};
$('command-close').onclick=()=>$('command-dialog').close();$('tool-close').onclick=()=>$('tool-dialog').close();$('command-open').onclick=openCommands;$('workspace-tools').onclick=openCommands;
$('settings-open').onclick=$('footer-settings').onclick=toolSettings;$('profiles-open').onclick=$('game-info').onclick=toolProfiles;$('help-open').onclick=toolGuide;$('shortcuts-open').onclick=toolShortcuts;$('find-open').onclick=toolFind;$('arrange-open').onclick=()=>openPlacement();$('layout-reset').onclick=resetLayout;$('preview-send').onclick=previewSend;
$('draft').oninput=saveDraft;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));
document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{const game=b.dataset.game;if(game!==profile().game)setProfile(games[game].members[0]);});
$('nav-toggle').onclick=()=>{const open=$('app').classList.toggle('nav-open');$('nav-toggle').setAttribute('aria-expanded',open);};
$('nav-close').onclick=()=>{$('app').classList.remove('nav-open');$('nav-toggle').setAttribute('aria-expanded','false');$('nav-toggle').focus();};
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){dragCanceled=true;clearDrag();if(!document.querySelector('dialog[open]')){$('app').classList.remove('nav-open');$('nav-toggle').setAttribute('aria-expanded','false');}return;}
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(document.querySelector('dialog[open]'))return;openCommands();}
  if(document.querySelector('dialog[open]'))return;
  if(e.ctrlKey&&e.key.toLowerCase()==='e'){e.preventDefault();toolEditor();}
  if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==='m'){e.preventDefault();openPlacement();}
  if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();previewSend();}
});
window.addEventListener('beforeunload',()=>{saveDraft();capturePositions();persist();});
window.addEventListener('resize',()=>{document.querySelectorAll('.floating-pane').forEach(el=>{const area=$('dock-area').getBoundingClientRect();el.style.left=Math.max(0,Math.min(parseFloat(el.style.left),area.width-el.offsetWidth))+'px';el.style.top=Math.max(0,Math.min(parseFloat(el.style.top),area.height-el.offsetHeight))+'px';});});
render();persist();
